#!/usr/bin/env python3
"""Generate Java 1.19.4 item names, stack limits and block-icon state mapping."""
import hashlib,json,sys,urllib.request
from pathlib import Path
base='https://raw.githubusercontent.com/PrismarineJS/minecraft-data/master/data/pc/1.19.4/'
def read(i,name):return Path(sys.argv[i]).read_bytes() if len(sys.argv)>i else urllib.request.urlopen(base+name,timeout=30).read()
raw=read(1,'items.json');braw=read(2,'blocks.json');blocks={b['name']:b['defaultState'] for b in json.loads(braw)}
lines=['/* Generated by tools/items.py; minecraft-data MIT, see vendor/MINECRAFT-DATA-LICENSE. */','/* items SHA256 '+hashlib.sha256(raw).hexdigest()+' */','/* blocks SHA256 '+hashlib.sha256(braw).hexdigest()+' */','static const McItemDef item_defs[] = {']
for i in json.loads(raw):
 n=i['name'];kind=1 if n.endswith('_sword') else 2 if n.endswith('_pickaxe') else 3 if n.endswith('_axe') else 4 if n.endswith(('_shovel','_hoe')) else 5 if n.endswith('_helmet') else 6 if n.endswith('_chestplate') else 7 if n.endswith('_leggings') else 8 if n.endswith('_boots') else 9 if n.endswith('bucket') else 10 if 'potion' in n or 'bottle' in n else 11 if 'book' in n or 'map' in n else 0
 color=0x506040|(int(hashlib.sha256(n.encode()).hexdigest()[:6],16)&0x9f9f9f)
 for prefix,c in [('diamond_',0x56d9d4),('iron_',0xc5cbd0),('golden_',0xf4d442),('netherite_',0x57484e),('wooden_',0xa17c4b),('stone_',0x858383),('leather_',0x965b38)]:
  if n.startswith(prefix):color=c
 lines.append('{%d,%s,%s,%d,%d,%d,0x%06x},'%(i['id'],json.dumps(n),json.dumps(i['displayName']),i['stackSize'],blocks.get(n,-1),kind,color))
lines.append('};');Path('src/item_data.inc').write_text('\n'.join(lines)+'\n')
